INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64543930', 64543930, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Naskah Analisis Kebijakan Komprehensif Isu Prioritas Pembangunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 90000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Maksud dari pengadaan konsultan ini adalah untuk menyediakan dukungan profesional dan teknis yang bersifat ahli guna meningkatkan kapasitas dan kapabilitas PAKK dalam menghasilkan dokumen analisis kebijakan yang mendalam, akurat, dan tepat waktu.', 'Ruang lingkup penugasan Konsultan Review dan Penyuntingan Analisis Kebijakan Pembangunan meliputi aktivitas-aktivitas berikut: Menyusun dokumen rencana kerja (laporan awal) yang mencakup strategi pendampingan, siklus review, jadwal kerja bulanan, serta standar penulisan dan penyuntingan naskah. Melakukan review atas perumusan masalah, fokus kajian, ruang lingkup, dan pertanyaan kunci pada naskah analisis kebijakan yang disusun PAKK. Melakukan review atas rancangan metodologi, rencana analisis, serta kecukupan data dan informasi untuk menjawab pertanyaan kajian. Memberikan masukan teknis kepada tim PAKK dalam penajaman struktur argumentasi, penafsiran temuan, serta perumusan rekomendasi kebijakan yang lebih implementatif. Melakukan penyuntingan naskah (penyuntingan substantif dan penyuntingan bahasa) untuk memastikan konsistensi alur, sistematika, istilah, serta keterbacaan, termasuk kerapian rujukan dan sitasi sesuai ketentuan internal yang berlaku. Melakukan koordinasi berkala dengan tim PAKK, termasuk partisipasi dalam rapat teknis, forum diskusi, dan proses review antartahap yang ditetapkan oleh PAKK. Melakukan review dan finalisasi dokumen berdasarkan masukan penelaah dan/atau pemangku kepentingan, serta memastikan kualitas akhir naskah sebelum ditetapkan sebagai dokumen final PAKK.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1615812);
