INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64504317', 64504317, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Electrocauter', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 59872800000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '1919 unit', 'Pengadaan dan distribusi Electrocauter', 'ECUs are line-powered, radiofrequency (RF) generators that deliver treatment current at a fundamental frequency within 0.3 MHz to 1MHz range and a maximum output power <50W. [RF generators having power output greater >50W are classified as Electrosurgical Units (see ISO 60601-2-2: 2019) and are intended primarily for the electrosurgical cutting and coagulation among many other modalities.] There is no globally recognized performance standard specifically for ECUs. ECUs are used in clinics and clinician office practices mainly for dermatology (e.g., removal of moles) and other disciplines requiring surface tissue desiccation, fulguration, and coagulation. Most units can be used in monopolar mode either with or without a neutral (return) electrode. However, coagulation mode typically requires higher power (>25W) and use of a neutral electrode on the patient.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1616118);
