INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64502719', 64502719, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'BADAN PENDAPATAN DAERAH', 'Jasa Pramu Layanan Umum Pengolah Data dan Koordinator Petugas Lapangan Kegiatan Verifikasi PBB-P2', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang (Kota)', 681000000, 'January 2026', 'APBD', 0, 1, '10 orang x 10 bulan', 'Tahapan pekerjaan yang dilakukan oleh Pramu Layanan Umum Pengolah Data Hasil Kegiatan Verifikasi PBB-P2 adalah sebagai berikut: a. Melaporkan jika terdapat objek di Daftar Hasil Rekaman (DHR) yang tidak dapat ditemukan meski NOP tersebut aktif; b. Melaporkan jika terdapat suatu objek yang ditemukan, namun tidak diketahui atau tidak teridentifikasi dengan jelas di Daftar Hasil Rekaman (DHR); c. Melakukan rekap data hasil penginputan data Verifikasi PBB-P2 yang telah dilakukan oleh Pramu Layanan Umum Petugas Lapangan Verifikasi PBB-P2; d. Melakukan pemetaan peta bidang dari data Verifikasi PBB-P2 yang telah dilakukan oleh Pramu Layanan Umum Petugas Lapangan Verifikasi PBB-P2. Tahapan pekerjaan yang dilakukan oleh Pramu Layanan Umum Koordinator Petugas Lapangan Kegiatan Verifikasi PBB-P2 adalah sebagai berikut: a. Memantau dan memonitor secara harian tim Pramu Layanan Umum Petugas Lapangan Verifikasi PBB-P2 pada tempat kegiatan Verifkasi PBB-P2 berlangsung; b. Merekap objek di Daftar Hasil Rekaman (DHR) yang tidak dapat ditemukan meski NOP tersebut aktif; c. Merekap objek di Daftar Hasil Rekaman (DHR) yang tidak dapat ditemukan. d. Merekap hasil kegiatan Verifikasi PBB-P2 secara keseluruhan dan membuat list data yang perlu penanganan, serta melaporkannya kepada PPK. e. Membantu petugas lapangan apabila hasil yang telah di datangi masih belum mencukup sesuai data DHR yang ada di setiap kelurahan;', 'A. Pramu Layanan Umum Koordinator Petugas Lapangan Kegiatan Verifikasi PBB-P2 1. Warga Negara Indonesia berusia minimal 19 (sembilan belas) tahun; 2. Memiliki rekening bank bjb dengan mutasi rekening pemasukan pernah mendapat pendapatan dari kegiatan di Pemerintahan; 3. Berpengalaman sebagai petugas lapangan kegiatan survey lapangan minimal selama 27 (dua puluh tujuh) bulan kerja; 4. Pendidikan minimal SMA atau sederajat; 5. Mampu mengoperasikan aplikasi pengola data; 6. Mempunyai HP dan paket aktif untuk survey; 7. Mempunyai kendaraan pribadi (Motor roda 2); 8. Memiliki alamat email aktif untuk melakukan pendaftaran; 9. Sehat jasmani dan rohani; 10. Mampu mengoperasikan komputer. B. Pramu Layanan Umum Pengolah Data Hasil Kegiatan Verifikasi PBB-P2 1. Warga Negara Indonesia berusia maksimal 40 (Empat Puluh) tahun; 2. Memiliki rekening bank bjb dengan mutasi rekening pemasukan pernah mendapat pendapatan dari kegiatan di Pemerintahan; 3. Berpengalaman sebagai pengolah data kegiatan minimal selama 9 (sembilan) bulan kerja; 4. Pendidikan minimal SMA atau sederajat; 5. Mempunyai paket internet aktif; 6. Mempunyai laptop pribadi; 7. Memiliki alamat email aktif untuk melakukan pendaftaran; 8. Sehat jasmani dan rohani; 9. Mampu mengoperasikan komputer.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1616855);
