INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64563470', 64563470, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS01 LEMBAGA PEMBINAAN KHUSUS ANAK KELAS II BANDA ACEH', 'Pengadaan Jasa Lainnya Tenaga Outsourching pada Lembaga Pembinaan Khusus Anak Kelas II Banda Aceh Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Aceh, Aceh Besar (Kab.)', 58500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '13 Bulan', 'Dalam rangka melaksanakan pekerjaan Pramukantor: orang, sarana dan prasarana yang biasa disebut dalam kategori objek vital pada Gedung Kantor Lembaga Pembinaan Khusus Anak Kelas II Banda Aceh - Aceh Tahun Anggaran 2026, yang dilakukan pada setiap hari secara rutin diperlukan bantuan tenaga jasa yang dilakukan oleh satuan Tenaga Pramukantor.', '1. Ruang Lingkup Pekerjaan Spesifikasi Tenaga Pramukantor • Menyiapkan, mengolah, dan memasak makanan sesuai menu, jadwal, dan kebutuhan yang telah ditetapkan. • Menjamin kualitas makanan yang disajikan, meliputi rasa, kebersihan, keamanan, dan kelayakan konsumsi. • Menyiapkan bahan makanan sebelum proses memasak serta memastikan bahan yang digunakan dalam kondisi baik dan layak. • Mengatur porsi penyajian makanan sesuai jumlah dan kebutuhan pengguna. • Menjaga kebersihan dan sanitasi area dapur, termasuk peralatan memasak, peralatan makan, serta area penyimpanan bahan makanan. • Membersihkan dan merapikan peralatan memasak dan area kerja setelah kegiatan memasak selesai. • Mengelola penyimpanan bahan makanan agar terjaga kebersihan, kesegaran, dan keamanannya. • Melakukan pencatatan dan pelaporan kebutuhan bahan makanan kepada penanggung jawab. • Memastikan peralatan dapur berfungsi dengan baik dan melaporkan apabila terdapat kerusakan. • Melaksanakan tugas lain yang berkaitan dengan kegiatan memasak dan pengelolaan dapur sesuai arahan atasan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1617163);
