INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64524604', 64524604, 'analyze_legacy', 'Kab. Karimun', 'kabkota', 'DINAS PENANAMAN MODAL DAN PELAYANAN TERPADU SATU PINTU', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Karimun (Kab.)', 714840, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Kertas HVS; Kertas HVS;', 'Ukuran A4 70 Gram; Ukuran F4 70 Gram;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1618931);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64504843', 64504843, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Spirometer', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 42077880000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '2.025 unit', 'Spirometer', 'Spirometers designed to perform all respiratory gas volume and flow measurements needed for diagnosis of basic pulmonary functions. These instruments measure quiet breathing, determining tidal volume, and trace deep inspirations, evaluating variables such as the maximum volume of gas that can be expired from the lungs (i.e., expiratory vital capacity [EVC]) and the maximum volume of gas that can be inspired into the lungs (i.e., inspiratory vital capacity [IVC]). The IVC test may be performed under static conditions (e.g., to determine the vital capacity) or as a dynamic test using maximum effort against time (e.g., to determine forced expiratory volume [FEV]). Diagnostic spirometers consist of a mechanical or electromechanical device with a computerized unit to process the data, volume and/or flow sensors, a display, and a graph recorder. Some instruments can also determine other parameters, such as oxygen intake and carbon dioxide expiration, either for both lungs simultaneously or for each one independently. These spirometers are intended to assess pulmonary status, to monitor diseases, and/or to evaluate treatment effectiveness and/or disability; they cannot determine lung volume, residual pulmonary, or total lung capacity. Instruments combining spirometry and pulse oximetry capabilities are also available.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1618932);
