INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64545095', 64545095, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Penyusunan Dokumen Analisis Kebijakan Transformasi Digital dan untuk Perencanaan Pembangunan Kewilayahan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Konsultan Junior Penyusunan Dokumen Analisis Kebijakan Transformasi Digital untuk Perencanaan Pembangunan Kewilayahan merupakan penugasan kepada individu yang bertanggung jawab untuk membantu dan mendukung kegiatan penyusunan analisis kebijakan PAKK. Pengadaan tersebut diharapkan mampu mendukung lancarnya proses kegiatan penyusunan analisis kebijakan oleh PAKK yang menyesuaikan dengan Standar Kompetensi Nasional Tahun Anggaran 2026.', 'Ruang lingkup kegiatan/pekerjaan Konsultan Junior Penyusunan Dokumen Analisis Kebijakan Transformasi Digital untuk Perencanaan Pembangunan Kewilayahan meliputi: a. Melakukan penelaahan teknis, spasial, dan regulatif terkait penerapan transformasi digital dan pemanfaatan Satu Data dalam proses perencanaan dan pengambilan keputusan pemerintah, serta implikasinya terhadap pembangunan nasional. b. Mengumpulkan, mengelola, dan mengolah data lintas sektor secara terstandar untuk menghasilkan catatan analitis serta rekomendasi teknis pembangunan wilayah yang mendukung analisis kebijakan berbasis data yang dihasilkan oleh PAKK. c. Melaksanakan koordinasi dan kolaborasi dengan unit internal Bappenas serta pemangku kepentingan eksternal terkait guna memastikan keterpaduan implementasi transformasi digital dan prinsip Satu Data dalam kegiatan perencanaan. d. Menyusun rekomendasi kebijakan yang menekankan kesesuaian dengan kerangka regulasi teknis, standar data nasional, serta karakteristik dan kebutuhan kewilayahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1619625);
